{
  "trigger": {
    "kind": "incident",
    "url": "https://acme.pagerduty.com/incidents/Q2X4",
    "incident_id": "INC-2417",
    "decided_at": "2026-09-12T02:14:00Z",
    "committed_at": "2026-09-12T02:15:40Z",
    "bridge_open_at_commit": true
  },
  "owner": "ic:alice",
  "inputs": [
    {"name": "options_considered", "value": [
      "disable the recommendations sidecar in eu-west-1 (chosen: isolates the failing dependency, 1 min to apply)",
      "roll back the full checkout release 41 -> 40 (rejected: 20 min, widens blast radius to all regions)",
      "do nothing / keep observing for 10 min (rejected: 5xx rate rising 0.4 pp per minute)"
    ]},
    {"name": "blast_radius", "value": "38% of checkout requests in eu-west-1 returning 5xx, approx. 1,900 req/min, 3 tenants on dedicated shards unaffected"},
    {"name": "rollback_trigger", "value": {
      "metric": "checkout_http_5xx_rate (grafana: checkout-overview)",
      "threshold": "above 2%",
      "window": "5 consecutive minutes",
      "rollback": "helm rollback checkout 41 -n prod-eu-west-1"
    }},
    {"name": "executor", "value": "sre:bob"}
  ],
  "decision": "Disable the recommendations sidecar in eu-west-1 now.",
  "evidence": [
    "https://grafana.acme.internal/d/checkout-overview?from=1789178400000&to=1789180200000&var-region=eu-west-1",
    "https://acme.pagerduty.com/incidents/Q2X4/alerts/A7",
    "https://acme.slack.com/archives/C0INC2417/p1789178040001200"
  ],
  "review": {
    "postmortem_date": "2026-09-15",
    "next_review_at": "2026-09-15",
    "outcome": {
      "rollback_trigger_fired": false,
      "blast_radius_matched": true,
      "measured_blast_radius": "36% of eu-west-1 checkout requests over 11 minutes",
      "reviewed_at": "2026-09-15"
    }
  }
}

{
  "trigger": {
    "kind": "incident",
    "url": "https://acme.pagerduty.com/incidents/Q2X4",
    "incident_id": "INC-2417",
    "decided_at": "2026-09-12T02:14:00Z",
    "committed_at": "2026-09-12T02:15:40Z",
    "bridge_open_at_commit": true
  },
  "owner": "sre:bob",
  "inputs": [
    {"name": "options_considered", "value": [
      "disable the recommendations sidecar in eu-west-1 (chosen)"
    ]},
    {"name": "blast_radius", "value": "some EU users seeing errors on checkout"},
    {"name": "rollback_trigger", "value": {
      "metric": "checkout errors",
      "threshold": "if it gets worse",
      "window": "a while",
      "rollback": "roll back"
    }},
    {"name": "executor", "value": "sre:bob"}
  ],
  "decision": "We should probably consider disabling the sidecar and look into the release.",
  "evidence": [
    "https://grafana.acme.internal/d/checkout-overview",
    "https://docs.acme.internal/runbooks/checkout"
  ],
  "review": {
    "postmortem_date": "2026-09-15",
    "next_review_at": "2026-12-15"
  }
}
